import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem103 corrige alegações sem alterar links ou preço',()=>{for(const [id,titulo,expected] of [["mlMLB5158506809","Kit 2 Body Splash Masculino Seduction Ocean 200ml Cada","Kit 2 Body Splash Masculino Seduction Ocean 200ml Cada"],["mlMLB5210159957","Oculos Polarizado De Sol Masculino Casual Pesca Praia Uv400","Óculos de sol — polarização e UV400 anunciados"],["mlMLB5217026798","Tenis Masculino Estilo Bota Adventure Nobuck Wonder","Tenis Masculino Estilo Bota Adventure Nobuck Wonder"]]){const p={id,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.notEqual(x.comentario,p.comentario);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
